import{_ as e,o as t,c as i,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-07-06","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-07-06","date":"2021-07-06T00:00:00.000Z","updated":"2021-08-25T00:00:00.000Z","tags":["Ceph","Orchestrator","设计文档","工具和流程","技术问题"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-07-06.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-07-06.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-07-06.md"};function o(s,l,n,h,p,u){return t(),i("div",null,[...l[0]||(l[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题：&quot;">​</a></h4><p>本次会议主要讨论了Ceph Orchestrator的设计决策和记录方式，以及与上游社区的协作策略。</p><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>设计文档的管理</strong>：</p><ul><li>讨论了是否需要编写详细的设计文档，或在会议记录中记录设计决策。</li><li>讨论了设计文档的公开性，以及是否应针对复杂设计创建文档。</li><li>分析了Rook Orchestrator的设计流程，包括存储类和PV的管理。</li></ul></li><li><p><strong>工具和流程的改进</strong>：</p><ul><li>探讨了使用Redmine、Trello等工具来管理项目和任务的可能性。</li><li>讨论了如何改进Redmine的使用，例如标签、过滤和问题分类。</li><li>讨论了如何将不同的工具如GitHub和Redmine更好地集成。</li></ul></li><li><p><strong>具体技术问题</strong>：</p><ul><li>分析了Ceph集群部署中的边缘情况和bug。</li><li>讨论了Rook Orchestrator的存储类和PV管理问题。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项： <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项：&quot;">​</a></h4><ol><li><p><strong>设计文档的管理</strong>：</p><ul><li>决定基于设计决策的复杂性来决定是否编写设计文档，并考虑公开部分重要文档。</li></ul></li><li><p><strong>工具和流程的改进</strong>：</p><ul><li>决定尝试改进Redmine的使用，包括标签和过滤问题。</li><li>决定探索如何更好地集成不同的工具。</li></ul></li><li><p><strong>具体技术问题</strong>：</p><ul><li>决定解决一些具体的部署问题。</li><li>决定测试和改进Rook Orchestrator的存储类和PV管理。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ol><li><p><strong>设计文档的管理</strong>：</p><ul><li>根据设计决策的复杂性来决定是否编写设计文档，并考虑公开部分重要文档。</li></ul></li><li><p><strong>工具和流程的改进</strong>：</p><ul><li>尝试改进Redmine的使用。</li><li>探索如何更好地集成不同的工具。</li></ul></li><li><p><strong>具体技术问题</strong>：</p><ul><li>解决一些具体的部署问题。</li><li>测试和改进Rook Orchestrator的存储类和PV管理。</li></ul></li></ol><h4 id="其他事项" tabindex="-1">其他事项： <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项：&quot;">​</a></h4><ul><li>讨论了Ceph在特定环境下的兼容性问题，如Python 3和容器管理工具。</li><li>讨论了如何更好地管理维护模式下的主机。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在讨论所有议题后结束，大家表示下周再见。</li></ul>',13)])])}const _=e(r,[["render",o]]);export{c as __pageData,_ as default};
